// @ts-nocheck
import { z } from "zod";
export const updateUserSchema = z.object({
    planTier: z.nativeEnum(PlanTier).optional(),
    subscriptionStatus: z.string().trim().max(80).nullable().optional(),
    aiCreditsDelta: z.number().int().min(-100000).max(100000).optional(),
    resetMonthlyUsage: z.boolean().optional(),
    role: z.nativeEnum(UserRole).optional(),
});
export const updateConfigSchema = z.object({
    stripeSecretKey: z.string().trim().min(1).optional(),
    stripeWebhookSecret: z.string().trim().min(1).optional(),
    paystackSecretKey: z.string().trim().min(1).optional(),
    paystackCurrency: z.string().trim().min(3).max(10).optional(),
    stripePricePlus: z.string().trim().min(1).optional(),
    stripePricePro: z.string().trim().min(1).optional(),
    stripePriceProRenewal: z.string().trim().min(1).optional(),
    stripePricePlusRenewal: z.string().trim().min(1).optional(),
    stripePriceCreditsPack: z.string().trim().min(1).optional(),
    stripePriceCvDeepReview: z.string().trim().min(1).optional(),
    stripePriceSopDetailedCritique: z.string().trim().min(1).optional(),
    paystackPlanCodePlus: z.string().trim().min(1).optional(),
    paystackPlanCodePro: z.string().trim().min(1).optional(),
    paystackPlanCodeProRenewal: z.string().trim().min(1).optional(),
    paystackPlanCodePlusRenewal: z.string().trim().min(1).optional(),
    paystackAmountCreditsMinor: z.number().int().min(0).optional(),
    displayPriceProGhs: z.number().min(0).optional(),
    displayPricePlusGhs: z.number().min(0).optional(),
    displayPriceCreditsPackGhs: z.number().min(0).optional(),
    creditUnitPriceGhs: z.number().min(0).optional(),
    displayPriceProRenewalGhs: z.number().min(0).optional(),
    displayPricePlusRenewalGhs: z.number().min(0).optional(),
    paystackAmountCvDeepReviewMinor: z.number().int().min(0).optional(),
    paystackAmountSopDetailedCritiqueMinor: z.number().int().min(0).optional(),
    allowanceFree: z.number().int().min(0).optional(),
    allowancePlus: z.number().int().min(0).optional(),
    allowancePro: z.number().int().min(0).optional(),
    freeSignupCredits: z.number().int().min(0).optional(),
    freeMonthlyCreditsGrant: z.number().int().min(0).optional(),
    creditsPackSize: z.number().int().min(1).optional(),
});
